from binary_replace import *
from ail import read_bytes, write_stdout_bytes
import sys

def binary_replace_count_in_range(text: str) -> int:
    token = text.strip()
    negative = token.startswith('-')
    if negative or token.startswith('+'):
        token = token[1:]
    if not token.isdigit():
        return 0
    token = token.lstrip('0')
    limit = '9223372036854775807'
    if negative:
        limit = '9223372036854775808'
    return len(token) < 19 or (len(token) == 19 and token <= limit)

def main() -> int:
    if len(sys.argv) != 4 and len(sys.argv) != 5:
        print('usage: binary_replace input old_hex new_hex [count]', file=sys.stderr)
        return 2
    try:
        old = bytes.fromhex(sys.argv[2])
        replacement = bytes.fromhex(sys.argv[3])
        count = -1
        if len(sys.argv) == 5:
            if not binary_replace_count_in_range(sys.argv[4]):
                raise ValueError
            count = int(sys.argv[4])
        data = read_bytes(sys.argv[1])
        write_stdout_bytes(binary_replace(data, old, replacement, count))
        return 0
    except ValueError:
        print('invalid hexadecimal value or replacement count', file=sys.stderr)
        return 2
    except OSError:
        print('binary input or output failed', file=sys.stderr)
        return 2
    return 0

if __name__ == "__main__":
    sys.exit(main())
